CREATE TABLE departments (id VARCHAR(64) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3));
CREATE TABLE employment_categories (id VARCHAR(64) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE users (id VARCHAR(64) PRIMARY KEY, google_id VARCHAR(191) UNIQUE NULL, name VARCHAR(191) NOT NULL, email VARCHAR(191) NOT NULL UNIQUE, code VARCHAR(64) UNIQUE NULL, avatar_url VARCHAR(1024), gender VARCHAR(32), phone VARCHAR(32), role VARCHAR(32) NOT NULL, department_id VARCHAR(64) NULL, category_id VARCHAR(64) NULL, status VARCHAR(32) NOT NULL, password_hash VARCHAR(255), birthday DATE NULL, scheduling_points INT NOT NULL DEFAULT 0, water_trip_count INT NOT NULL DEFAULT 0, created_at DATETIME(3), updated_at DATETIME(3), activated_at DATETIME(3), activated_by VARCHAR(64), FOREIGN KEY (department_id) REFERENCES departments(id), FOREIGN KEY (category_id) REFERENCES employment_categories(id));
CREATE TABLE app_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value JSON NOT NULL, updated_at DATETIME(3) NOT NULL);
CREATE TABLE fund_periods (id VARCHAR(64) PRIMARY KEY, year SMALLINT NOT NULL, month TINYINT NOT NULL, opening_balance BIGINT NOT NULL DEFAULT 0, payment_deadline DATE NULL, reminder_days_before JSON NULL, email_reminder_enabled BOOLEAN NOT NULL DEFAULT FALSE, updated_at DATETIME(3), UNIQUE KEY uq_fund_period (year, month));
CREATE TABLE fund_member_payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, fund_period_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, paid BOOLEAN NOT NULL DEFAULT FALSE, amount BIGINT NOT NULL DEFAULT 0, paid_at DATETIME(3) NULL, payment_status VARCHAR(32), order_code BIGINT NULL UNIQUE, payment_link_id VARCHAR(191), payment_reference VARCHAR(191), approved_by VARCHAR(64), updated_at DATETIME(3), UNIQUE KEY uq_fund_user (fund_period_id,user_id), FOREIGN KEY (fund_period_id) REFERENCES fund_periods(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE fund_transactions (id VARCHAR(64) PRIMARY KEY, fund_period_id VARCHAR(64) NOT NULL, kind ENUM('income','expense') NOT NULL, title VARCHAR(191) NOT NULL, category VARCHAR(64) NOT NULL, amount BIGINT NOT NULL, note TEXT, user_id VARCHAR(64), occurred_at DATETIME(3) NOT NULL, created_by VARCHAR(64), created_at DATETIME(3), updated_at DATETIME(3), INDEX ix_fund_transaction (fund_period_id,kind,occurred_at), FOREIGN KEY (fund_period_id) REFERENCES fund_periods(id));
CREATE TABLE fund_reminder_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, fund_period_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, trigger_type VARCHAR(32) NOT NULL, reminder_date DATE NOT NULL, sent_at DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, error_message TEXT, UNIQUE KEY uq_reminder (fund_period_id,user_id,trigger_type,reminder_date), FOREIGN KEY (fund_period_id) REFERENCES fund_periods(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE asset_transactions (id VARCHAR(64) PRIMARY KEY, type ENUM('import','export') NOT NULL, asset_code VARCHAR(100) NOT NULL, name VARCHAR(191) NOT NULL, transaction_date DATE NOT NULL, quantity INT NOT NULL, location VARCHAR(191), person VARCHAR(191), note TEXT, created_at DATETIME(3), updated_at DATETIME(3), INDEX ix_asset_stock (asset_code,transaction_date));
CREATE TABLE water_schedules (id VARCHAR(64) PRIMARY KEY, year SMALLINT NOT NULL, month TINYINT NOT NULL, week_index TINYINT NOT NULL, schedule_date DATE, schedule_time TIME, required_people INT NOT NULL, status VARCHAR(32), note TEXT, created_at DATETIME(3), updated_at DATETIME(3), INDEX ix_water_period (year,month,week_index));
CREATE TABLE water_schedule_participants (id BIGINT AUTO_INCREMENT PRIMARY KEY, schedule_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE KEY uq_schedule_user (schedule_id,user_id), FOREIGN KEY (schedule_id) REFERENCES water_schedules(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE water_exemptions (user_id VARCHAR(64) PRIMARY KEY, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id VARCHAR(64) PRIMARY KEY, admin_id VARCHAR(64), action VARCHAR(100) NOT NULL, target_type VARCHAR(64), target_id VARCHAR(64), details TEXT, ip VARCHAR(64), timestamp DATETIME(3) NOT NULL, INDEX ix_audit_target (target_type,target_id), INDEX ix_audit_time (timestamp));
